CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_study_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,avatar_url) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),NEW.raw_user_meta_data->>'avatar_url'); RETURN NEW; END $$;
CREATE TRIGGER study_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_study_profile();
CREATE TABLE public.study_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL CHECK(kind IN ('contest','subject','topic','questions','mock','goal','review','link')), payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.study_items TO authenticated; GRANT ALL ON public.study_items TO service_role;
ALTER TABLE public.study_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_items ON public.study_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX study_items_owner ON public.study_items(user_id,kind);
CREATE TABLE public.study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), contest_ids uuid[] NOT NULL, subject_id uuid NOT NULL, topic_id uuid, state text NOT NULL DEFAULT 'running' CHECK(state IN ('running','paused','finished')), started_at timestamptz NOT NULL DEFAULT now(), running_since timestamptz DEFAULT now(), elapsed_seconds numeric NOT NULL DEFAULT 0 CHECK(elapsed_seconds>=0), finished_at timestamptz, pauses jsonb NOT NULL DEFAULT '[]', notes text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.study_sessions TO authenticated; GRANT ALL ON public.study_sessions TO service_role;
ALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_sessions ON public.study_sessions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE UNIQUE INDEX one_active_session ON public.study_sessions(user_id) WHERE state<>'finished';
CREATE INDEX study_sessions_owner ON public.study_sessions(user_id,started_at);
CREATE FUNCTION public.study_timer(action text, session_id uuid DEFAULT NULL, contests uuid[] DEFAULT NULL, subject uuid DEFAULT NULL, topic uuid DEFAULT NULL, note text DEFAULT '') RETURNS public.study_sessions LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s public.study_sessions; t timestamptz:=clock_timestamp(); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF action='start' THEN IF array_length(contests,1) IS NULL OR subject IS NULL THEN RAISE EXCEPTION 'Selecione concurso e disciplina'; END IF; IF EXISTS(SELECT 1 FROM unnest(contests) c WHERE NOT EXISTS(SELECT 1 FROM study_items WHERE id=c AND user_id=auth.uid() AND kind='contest')) OR NOT EXISTS(SELECT 1 FROM study_items WHERE id=subject AND user_id=auth.uid() AND kind='subject' AND (payload->>'contest_id')::uuid=ANY(contests)) THEN RAISE EXCEPTION 'Conteúdo inválido'; END IF; IF topic IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=topic AND user_id=auth.uid() AND kind='topic' AND payload->>'subject_id'=subject::text) THEN RAISE EXCEPTION 'Tópico inválido'; END IF; INSERT INTO study_sessions(contest_ids,subject_id,topic_id) VALUES(contests,subject,topic) RETURNING * INTO s; RETURN s; END IF; SELECT * INTO s FROM study_sessions WHERE id=session_id AND user_id=auth.uid() FOR UPDATE; IF s.id IS NULL THEN RAISE EXCEPTION 'Sessão não encontrada'; END IF; IF s.state='finished' THEN RETURN s; END IF; IF action='pause' AND s.state='running' THEN UPDATE study_sessions SET elapsed_seconds=elapsed_seconds+greatest(0,extract(epoch FROM t-running_since)),running_since=NULL,state='paused',pauses=pauses||jsonb_build_array(jsonb_build_object('start',t)) WHERE id=s.id RETURNING * INTO s; ELSIF action='resume' AND s.state='paused' THEN UPDATE study_sessions SET running_since=t,state='running',pauses=jsonb_set(pauses,ARRAY[(jsonb_array_length(pauses)-1)::text,'end'],to_jsonb(t)) WHERE id=s.id RETURNING * INTO s; ELSIF action='finish' THEN UPDATE study_sessions SET elapsed_seconds=elapsed_seconds+CASE WHEN state='running' THEN greatest(0,extract(epoch FROM t-running_since)) ELSE 0 END, running_since=NULL,state='finished',finished_at=t,notes=note,pauses=CASE WHEN state='paused' THEN jsonb_set(pauses,ARRAY[(jsonb_array_length(pauses)-1)::text,'end'],to_jsonb(t)) ELSE pauses END WHERE id=s.id RETURNING * INTO s; ELSIF action NOT IN ('pause','resume','finish') THEN RAISE EXCEPTION 'Ação inválida'; END IF; RETURN s; END $$;
REVOKE ALL ON FUNCTION public.study_timer(text,uuid,uuid[],uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.study_timer(text,uuid,uuid[],uuid,uuid,text) TO authenticated;
CREATE TABLE public.study_catalog (id text PRIMARY KEY, label text NOT NULL, source_url text NOT NULL, year integer NOT NULL, content jsonb NOT NULL, verification text NOT NULL DEFAULT 'Conteúdo conferido; vigência não confirmada');
GRANT SELECT ON public.study_catalog TO anon,authenticated; GRANT ALL ON public.study_catalog TO service_role;
ALTER TABLE public.study_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_catalog ON public.study_catalog FOR SELECT TO anon,authenticated USING(true);